const requestEnvelope = $json || {};
const headers = requestEnvelope.headers || {};
const body = requestEnvelope.body || requestEnvelope;
const expectedSecret = $env.N8N_SHARED_SECRET || '';
const receivedSecret = headers['x-pline-v3-shared-secret'] || headers['X-Pline-V3-Shared-Secret'] || '';
if (expectedSecret && receivedSecret !== expectedSecret) {
  throw new Error('invalid_n8n_shared_secret');
}
return [{ json: {
  request_id: body.request_id || '',
  line_event_id: body.line_event_id || '',
  reply_token: body.reply_token || '',
  user_id: body.user_id || '',
  message_text: body.message_text || '',
  received_at: body.received_at || new Date().toISOString(),
  allowed_intents: ['idea_create', 'codex_task', 'clarify', 'unsupported'],
  project_scope: '菲比 LINE 智能助理_03',
  project_root: '/Users/phoebe/Documents/菲比 LINE 智能助理_03'
} }];

const input = $fromAI('idea_text', 'One sentence idea text to save', 'string');
return JSON.stringify({
  tool_called: 'idea_create',
  saved: true,
  saved_record: 1,
  idea_text: input
});

return JSON.stringify({
  tool_called: 'codex_task',
  task_id: `pline-v3-codex-${Date.now()}`,
  action: 'create_smoke_file',
  target_path: '/Users/phoebe/Documents/菲比 LINE 智能助理_03/codex-smoke.txt',
  content: 'Codex 已打通'
});

const agent = $json || {};
const input = $('Normalize Input').first().json || {};
let parsed = {};
try {
  parsed = typeof agent.output === 'string' ? JSON.parse(agent.output) : agent.output || agent;
} catch (error) {
  parsed = { intent: 'clarify', reply_text: '我需要再確認一次你的需求。', status: 'accepted' };
}
const requestId = input.request_id || '';
const messageText = input.message_text || '';
const allowed = ['idea_create', 'codex_task', 'clarify', 'unsupported'];
let intent = allowed.includes(parsed.intent) ? parsed.intent : '';
if (!intent) {
  intent = /codex|測試檔案|建立測試檔案/i.test(messageText) ? 'codex_task' : (/記一下|記錄|想法/.test(messageText) ? 'idea_create' : 'unsupported');
}
const status = intent === 'unsupported' || intent === 'clarify' ? 'accepted' : (parsed.status || 'completed');
const base = {
  request_id: requestId,
  intent,
  reply_text: parsed.reply_text || (intent === 'codex_task' ? 'Codex 任務已建立。' : intent === 'idea_create' ? '已記下這個想法。' : '目前只支援記想法或建立 Codex 測試任務。'),
  status
};
if (intent === 'idea_create') {
  return [{ json: {
    ...base,
    tool_called: 'idea_create',
    saved: true,
    saved_record: 1,
    record: 1
  } }];
}
if (intent === 'codex_task') {
  return [{ json: {
    ...base,
    tool_called: 'codex_task',
    task_id: parsed.task_id || 'pline-v3-codex-' + Date.now(),
    codex_task: 1,
    action: 'create_smoke_file',
    target_path: '/Users/phoebe/Documents/菲比 LINE 智能助理_03/codex-smoke.txt',
    content: 'Codex 已打通'
  } }];
}
return [{ json: base }];
